import React from "react";
import { useNavigate } from "react-router-dom";

const StudentSidebar = ({ onLogout }) => {
    const features = [
        { id: 1, name: "View and Manage Deadlines", icon: "fas fa-calendar-alt" },
        // Other features
        { id: 12, name: "Logout", icon: "fas fa-sign-out-alt" },
    ];

    const navigate = useNavigate();

    return (
        <aside className="dashboard-sidebar">
            <h2>Features</h2>
            <ul className="sidebar-list">
                {features.map((feature) => (
                    <li
                        key={feature.id}
                        className={`sidebar-item ${feature.name === "Logout" ? "logout" : ""}`}
                        onClick={() => {
                            if (feature.name === "Logout") {
                                onLogout();
                            } else if (feature.name === "View and Manage Deadlines") {
                                navigate("/deadlines");
                            }
                        }}
                    >
                        <i className={feature.icon}></i>
                        <span>{feature.name}</span>
                    </li>
                ))}
            </ul>
        </aside>
    );
};

export default StudentSidebar;
